from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from waffle.models import Switch

@api_view(['PATCH'])
@permission_classes([IsAuthenticated])
def toggle_runtime_switch(request, name: str):
    # Enforce administrative permissions for system runtime switches
    if not request.user.is_staff or not request.user.has_perm('waffle.change_switch'):
        return Response({'error': 'Superuser or staff permissions required'}, status=status.HTTP_403_FORBIDDEN)

    try:
        switch = Switch.objects.get(name=name)
    except Switch.DoesNotExist:
        return Response({'error': 'Switch not found'}, status=status.HTTP_404_NOT_FOUND)

    new_state = request.data.get('active')
    if new_state is not None:
        switch.active = bool(new_state)
        switch.save(update_fields=['active'])

    return Response({'switch': switch.name, 'active': switch.active})
